const files = [];
for (let i=0; i<$input.all().length; i++) {
 const item = $input.all()[i];
 if (item.json.error) return [{json: item.json}];
 const bytes = await this.helpers.getBinaryDataBuffer(i, 'data');
 files.push({...item.json, text: bytes.toString('utf8')});
}
const input = files.find(f=>f.relative_path==='input.txt');
const output = files.find(f=>f.relative_path==='output.txt');
const verified = files.length===2 && input?.text==='hello from n8n\n' && output?.text==='HELLO FROM N8N\n' && input.sha256===$('Upload input file').first().json.sha256;
return [{json:{verified, files}}];

const names = ['List boxes','Get demo box','Make input file','Upload input file','Run command','Get execution status','List recent executions','Download demo directory','Collect files','Read box metrics','Stop demo box','Start demo box','Delete demo box'];
const failures = names.flatMap(name => $(name).all().filter(i=>i.json.error).map(i=>({node:name,...i.json})));
const files = $('Collect files').first().json;
const command = $('Run command').first().json;
const deleted = $('Delete demo box').first().json.deleted === true;
if (failures.length || !files.verified || command.exit_code!==0 || !deleted) throw new Error('Demo did not fully succeed. Cleanup attempted: '+deleted+'. Inspect node outputs: '+JSON.stringify(failures));
return [{json:{ok:true, box_id:$('Create demo box').first().json.box_id, deleted, stdout:command.stdout, stderr:command.stderr, files:files.files, next:'Duplicate the workflow or copy an example node; keep cleanup and review the notes.'}}];
